define({"topics":[{"title":"Determining service pack information","shortdesc":"<p class=\"shortdesc\">Find which service pack is installed on the system before attempting to load any service pack update.<\/p>","href":"t_DeterminingSystemServicePackInformation.html","attributes":{"data-id":"id_2001448"},"menu":{"hasChildren":false},"tocID":"id_2001448-d46e118307","topics":[]},{"title":"Accessing Guided Install patches","shortdesc":"<p class=\"shortdesc\">Access the patches that are available on the system disk, CD\/DVD, and host computer.<\/p>","href":"t_AccessingGuidedInstallPatches.html","attributes":{"data-id":"id_2002842"},"menu":{"hasChildren":false},"tocID":"id_2002842-d46e118512","topics":[]},{"title":"Loading software updates from the repository<span class=\"ph\"> or CD\/DVD<\/span>","shortdesc":"<p class=\"shortdesc\">You can install software updates to the host computer from the repository or from a CD\/DVD.<\/p>","href":"t_LoadingSoftwareUpdatesFromRepositoryOrCDDVD.html","attributes":{"data-id":"id_2002356"},"menu":{"hasChildren":false},"tocID":"id_2002356-d46e118616","topics":[]},{"title":"Removing software updates","shortdesc":"<p class=\"shortdesc\">Procedure for deleting an installed update from the system.<\/p>","href":"t_RemovingSoftwareUpdates.html","attributes":{"data-id":"id_2002357"},"menu":{"hasChildren":false},"tocID":"id_2002357-d46e118722","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_29.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e118826","topics":[]}]});